import os
import json
import boto3
from botocore.exceptions import BotoCoreError, ClientError

_sqs = boto3.client("sqs", region_name=os.getenv("AWS_REGION", "us-east-1"))

DEAD_LETTER_QUEUE_URL = os.environ["AWS_SQS_DEAD_LETTER_QUEUE_URL"]


def send_to_dead_letter(message_body, attributes=None):
    if not isinstance(message_body, str):
        message_body = json.dumps(message_body, separators=(",", ":"))

    message_attributes = {}
    if attributes:
        for key, value in attributes.items():
            if value is None:
                continue
            if isinstance(value, bytes):
                message_attributes[key] = {
                    "DataType": "Binary",
                    "BinaryValue": value,
                }
            else:
                message_attributes[key] = {
                    "DataType": "String",
                    "StringValue": str(value),
                }

    try:
        response = _sqs.send_message(
            QueueUrl=DEAD_LETTER_QUEUE_URL,
            MessageBody=message_body,
            MessageAttributes=message_attributes,
        )
        return {
            "ok": True,
            "message_id": response["MessageId"],
            "md5_of_body": response.get("MD5OfMessageBody"),
        }
    except (BotoCoreError, ClientError) as e:
        return {
            "ok": False,
            "error": str(e),
        }
